package edu.washington.cs.mut.testrunner;

import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

import org.junit.runner.JUnitCore;
import org.junit.runner.Request;
import org.junit.runner.Result;

import org.junit.runner.notification.Failure;

/**
 * Simple JUnit test runner that takes a single test class or test method as
 * command line argument and executes only this class or method.
 *
 * Examples:
 * org.x.y.z.TestClass::testMethod1
 *   -> only testMethod1 in TestClass gets executed
 *
 * org.x.y.z.TestClass
 *   -> only TestClass (with all its test methods) gets executed
 */
class SingleTestRunner {

    private static void usageAndExit() {
        System.err.println("usage: java " + SingleTestRunner.class.getName() + " testClass[::testMethod]");
        throw new RuntimeException("Invalid usage");
    }

    public static void main(String ... args) {
        int exitCode = 0;
        try {
            exitCode = execute(args);
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
            exitCode = 1;
        }
        if (exitCode != 0) {
            throw new RuntimeException("Test execution failed with exit code: " + exitCode);
        }
    }

    private static int execute(String[] args) {
        if (args == null || args.length != 1) {
            usageAndExit();
        }

        String arg = args[0];
        if (arg == null || arg.trim().isEmpty()) {
            usageAndExit();
        }

        Matcher m = Pattern.compile("(?<className>[^:]+)(::(?<methodName>[^:]+))?").matcher(arg);
        if (!m.matches()) {
            usageAndExit();
        }

        // Determine and load test class
        String className = m.group("className");
        if (className == null || className.trim().isEmpty()) {
            System.err.println("Invalid class name");
            return 1;
        }

        Class<?> clazz = null;
        try {
            clazz = Class.forName(className);
        } catch(Exception e) {
            System.err.println("Couldn't load class (" + className + "): " + e.getMessage());
            return 1;
        }

        // Check whether a test method is specified
        String methodName = m.group("methodName");
        Request request = null;
        try {
            if (methodName != null && !methodName.trim().isEmpty()) {
                request = Request.method(clazz, methodName.trim());
            } else {
                request = Request.aClass(clazz);
            }
        } catch (Exception e) {
            System.err.println("Couldn't create test request: " + e.getMessage());
            return 1;
        }

        if (request == null) {
            System.err.println("Failed to create test request");
            return 1;
        }

        return executeTest(request);
    }

    private static int executeTest(Request request) {
        if (request == null) {
            System.err.println("Test request is null");
            return 1;
        }

        try {
            Result result = new JUnitCore().run(request);
            if (result == null) {
                System.err.println("Test result is null");
                return 1;
            }

            if (result.wasSuccessful()) {
                System.out.println("Tests successful (" + result.getRunCount() + " tests)");
                return 0;
            } else {
                System.err.println("Tests failed (" + result.getRunCount() + " tests, " 
                    + result.getFailureCount() + " failures)");
                List<Failure> failures = result.getFailures();
                if (failures != null) {
                    for (Failure failure : failures) {
                        if (failure != null) {
                            System.err.println("Failure: " + failure.getDescription().getDisplayName());
                            Throwable exception = failure.getException();
                            if (exception != null) {
                                System.err.println("  " + exception.getMessage());
                            }
                        }
                    }
                }
                return 1;
            }
        } catch (Exception e) {
            System.err.println("Error executing tests: " + e.getMessage());
            return 1;
        }
    }
}
